import base64, io, zipfile, sys, tempfile, os
from pathlib import Path
os.environ.setdefault('OPENAI_MODEL','gpt-5.6-luna')
PAYLOAD=''
root=Path(tempfile.gettempdir())/'pdp_app_payload'
marker=root/'.ready'
if not marker.exists():
    root.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as z: z.extractall(root)
    marker.write_text('1')
sys.path.insert(0,str(root))
from app import app
